from langflow.custom import Component
from langflow.io import MessageTextInput, Output
from langflow.schema.message import Message
import json

class EnvironmentalRiskAgent(Component):
    display_name = "🌿 Environmental Risk"
    description = "Extracts 🌿 Environmental Risk output from the orchestrator result"

    inputs = [
        MessageTextInput(name="input", display_name="Pipeline Result", is_list=False),
    ]

    outputs = [
        Output(display_name="Agent Output", name="output", method="build_output"),
    ]

    def build_output(self) -> Message:
        try:
            data = json.loads(self.input)
            # Try multiple key patterns the backend might use
            result = (
                data.get("environmental_risk_output")
                or data.get("environmental_risk")
                or data.get("🌿 Environmental Risk")
                or data.get("agents", {}).get("environmental_risk")
                or data.get("agents", {}).get("🌿 Environmental Risk")
                or "🌿 Environmental Risk: awaiting data"
            )
            if isinstance(result, dict):
                result = json.dumps(result, indent=2)
            return Message(text=str(result))
        except Exception as e:
            return Message(text=f"🌿 Environmental Risk: {e}")

